/* Install our safe click target before Firebase installs its own handler. */
self.addEventListener('notificationclick', (event) => {
  const payload = event.notification.data;
  const data = payload?.FCM_MSG?.data || payload;
  if (data?.notification_type !== 'batch_deleted') return;
  event.stopImmediatePropagation();
  event.notification.close();
  // Ignore batch_id and any remote click URL: this batch has been deleted.
  const target = new URL('org/batch-status', self.registration.scope).href;
  event.waitUntil((async () => {
    const tabs = await self.clients.matchAll({ type: 'window', includeUncontrolled: true });
    for (const tab of tabs) {
      if (!tab.url.startsWith(self.registration.scope)) continue;
      try {
        const destination = await tab.navigate(target);
        await (destination || tab).focus();
        return;
      } catch { /* Try the next available tab, then open a new one. */ }
    }
    await self.clients.openWindow(target);
  })());
});

// Generated by the Vite plugin from public Web App config; no server credentials.
try { self.__TRUMARKZ_FIREBASE_CONFIG__ = JSON.parse(new URL(self.location.href).searchParams.get('config') || 'null'); }
catch { self.__TRUMARKZ_FIREBASE_CONFIG__ = null; }
importScripts('./firebase-messaging-runtime.js');
